spf = list(range(N + 1))
for i in range(2, int(N ** 0.5) + 1):
    if spf[i] == i:
        for j in range(i * i, N + 1, i):
            if spf[j] == j: spf[j] = i
def factors(x):
    out = []
    while x > 1:
        p = spf[x]; out.append(p)
        while x % p == 0: x //= p
    return out

